@gene('Z18a', 'once per turn: the distance field to a fight an ally just announced nearby, else to the goals plus enemy champions worth hunting', parents=['s3'])
def update() -> None:
    r = rally_tiles()
    if size(r) > 0:
        GF = field(r)
    else:
        GF = field(goals() | hunt_tiles())
```

## EDITABLE gene rally_tiles (called by update)
```python
@gene('Z276b', 'an ally fight announced in the last 3 rounds within 12 tiles, worth joining when I am healthy and carrying fewer than 5 gems', parents=['Z18a'])
def rally_tiles() -> Tiles:
    acc = near(tile(-5, -5), 0)
    if gems() >= 5 or me().health_frac < 0.6:
        return acc
    age = round() - 256 * floor(round() / 256) - read_shared(2)
    if age < 0:
        age += 256
    if age > 3:
        return acc
    t = tile(read_shared(0), read_shared(1))
    if valid(t) and dist(t, me().pos) <= 12 and dist(t, me().pos) > 1:
        acc = near(t, 1)
    return acc
```

## EDITABLE gene goal_field (called by progress)
